#!/usr/bin/env bash
# Add "Rows per page" pagination to the Licenses page's three tables
# (Software Titles: 4/page default; License Purchases and License
# Inventory: 25/page default) - matching hardware-page.tsx's own
# pagination convention. Generated by gen_deploy_licenses_pagination.py -
# do not hand-edit.
#
# No ordering dependency on any other outstanding script.
#
# Run this from the repo root on the server.
set -uo pipefail

sec() { echo ""; echo "=== $* ==="; echo "=== $* ===" >&2; }

FAIL=0

sec "0. Confirm repo root"
if [ ! -d "frontend/app/pages/licenses" ]; then
    echo "!!! Expected directories not found under $(pwd) - run this from the repo root."
    exit 1
fi

sec "1. Pre-flight: verify every touched file is exactly what was confirmed"
if [ ! -f "frontend/app/pages/licenses/licenses-page.tsx" ]; then
    echo "!!! frontend/app/pages/licenses/licenses-page.tsx not found - aborting, nothing written yet."
    FAIL=1
else
    h=$(git hash-object "frontend/app/pages/licenses/licenses-page.tsx")
    if [ "$h" != "2a255ba9d2c410196db1df0c87c2ede9d697b272" ]; then
        echo "!!! frontend/app/pages/licenses/licenses-page.tsx does not match the expected pre-deploy hash."
        echo "    expected: 2a255ba9d2c410196db1df0c87c2ede9d697b272"
        echo "    actual:   $h"
        echo "    If this matches the POST hash instead"
        echo "    (a727573a776e21b86fc9c62c5a1e3777263d0d8b), this script already ran successfully -"
        echo "    nothing more to do, this is not an error."
        echo "    Otherwise: this file has changed on the server since it was last"
        echo "    verified - do not proceed."
        FAIL=1
    fi
fi

if [ "$FAIL" != "0" ]; then
    echo ""
    echo ">>> Pre-flight checks failed - nothing was written. See messages above."
    exit 1
fi
echo "All pre-flight checks passed."

sec "2. Writing files"
mkdir -p "$(dirname "frontend/app/pages/licenses/licenses-page.tsx")"
base64 -d > "frontend/app/pages/licenses/licenses-page.tsx.tmp" <<'B64EOF'

B64EOF
mv "frontend/app/pages/licenses/licenses-page.tsx.tmp" "frontend/app/pages/licenses/licenses-page.tsx"
echo "wrote frontend/app/pages/licenses/licenses-page.tsx"

sec "3. Post-flight: verify every written file matches the expected final hash"
POSTFAIL=0
h=$(git hash-object "frontend/app/pages/licenses/licenses-page.tsx")
if [ "$h" != "a727573a776e21b86fc9c62c5a1e3777263d0d8b" ]; then
    echo "!!! frontend/app/pages/licenses/licenses-page.tsx does not match the expected post-deploy hash (expected a727573a776e21b86fc9c62c5a1e3777263d0d8b, got $h)"
    POSTFAIL=1
else
    echo "OK: frontend/app/pages/licenses/licenses-page.tsx"
fi

if [ "$POSTFAIL" != "0" ]; then
    echo ""
    echo ">>> Post-deploy verification failed - do not restart the containers; investigate before proceeding."
    exit 1
fi

sec "4. Done"
echo "Files written and verified. Next steps:"
echo "  1. git add -A && git commit  (commit this on the server's own checkout)"
echo "  2. docker compose build frontend && docker compose up -d frontend"
echo "     (frontend-only, no migration, no backend change)"
echo "  3. Open the Licenses page - Software Titles now shows 4 rows per page"
echo "     by default, License Purchases and License Inventory show 25 - each"
echo "     with a \"Rows per page\" dropdown and prev/next controls at the bottom"
echo "     of its table"
echo ">>> DONE"
